/**
 * Computes a real bounding box directly from a path's own 'd' string —
 * generic for any country in COUNTRY_PATHS, not a per-country lookup
 * table, so visual weight scales automatically as more countries are
 * added rather than needing a hand-tuned exception per new small country.
 * These source paths use only moveto/lineto commands (verified when the
 * geometry was first extracted — no curves), so this deliberately doesn't
 * handle curve commands; it would need extending if a future source path
 * ever contains them.
 */
export function getPathBBox(d: string): { width: number; height: number; area: number } {
  const tokens = d.match(/[a-zA-Z]|-?\d*\.?\d+(?:e-?\d+)?/g) ?? [];
  let i = 0, x = 0, y = 0, mode = 'm';
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  while (i < tokens.length) {
    const t = tokens[i];
    if (/[a-zA-Z]/.test(t)) { mode = t; i++; continue; }
    if (mode === 'm' || mode === 'l') {
      x += parseFloat(tokens[i]); y += parseFloat(tokens[i + 1]); i += 2;
      if (mode === 'm') mode = 'l';
    } else if (mode === 'M' || mode === 'L') {
      x = parseFloat(tokens[i]); y = parseFloat(tokens[i + 1]); i += 2;
      if (mode === 'M') mode = 'L';
    } else if (mode === 'z' || mode === 'Z') {
      i++; continue;
    } else {
      i++; continue;
    }
    minX = Math.min(minX, x); maxX = Math.max(maxX, x);
    minY = Math.min(minY, y); maxY = Math.max(maxY, y);
  }
  const width = maxX - minX, height = maxY - minY;
  return { width, height, area: width * height };
}

